467	/// What the structural answer says of a component that decides which of the checker's props a collapsed layer takes
468	/// (the merge's `layer_checker_props`): the props it lists, the source each names (`parent`), and its inheritance layers, their
469	/// sources and members. A [`SemanticTarget`] carries it in a [`Layering`], so the checker can leave unconverted what the
470	/// merge leaves to a layer.
471	#[derive(Debug, Clone, Default, PartialEq, Eq, Hash)]
472	pub struct LayerFacts {
473	    /// The names of the props the structural answer lists.
474	    listed: std::collections::BTreeSet<String>,
475	    /// The `parent` of each prop it lists, each once.
476	    parents: Vec<PropParent>,
477	    /// Each inheritance layer's source, by type name and file.
478	    sources: Vec<(String, String)>,
479	    /// The members of every inheritance layer.
480	    members: std::collections::BTreeSet<String>,
481	    /// The notable members of its collapsed layers it does not list, with their source ([`layer_notable`]).
482	    notable: Vec<(String, PropParent)>,
483	}
484	
485	/// The notable members (`className`, `style`, …) of `entry`'s collapsed layers that it does not list itself, each with
486	/// its layer's source: the merge merges the checker's answer for each and moves it back to `notableInherited`.
487	fn layer_notable(entry: &ComponentEntry) -> Vec<(String, PropParent)> {
488	    let notable_names = crate::react_types::notable_html_attrs("");
489	    entry
490	        .inheritance
491	        .iter()
492	        .filter(|layer| layer.html_element.is_none())
493	        .flat_map(|layer| {
494	            layer
495	                .members
496	                .iter()
497	                .filter(|name| notable_names.contains(&name.as_str()) && !entry.props.contains_key(*name))
498	                .map(|name| {
499	                    (name.clone(), PropParent { name: layer.type_name.clone(), file_name: layer.file_name.clone() })
500	                })
501	        })
502	        .collect()
503	}
504	
505	impl LayerFacts {
506	    /// What `entry`, a structural answer, says.
507	    pub fn of(entry: &ComponentEntry) -> Self {
508	        let mut parents: Vec<PropParent> = Vec::new();
509	        for parent in entry.props.values().filter_map(|prop| prop.parent.as_ref()) {
510	            if !parents.contains(parent) {
511	                parents.push(parent.clone());
512	            }
513	        }
514	        Self {
515	            listed: entry.props.keys().cloned().collect(),
516	            parents,
517	            sources: entry.inheritance.iter().map(|layer| (layer.type_name.clone(), layer.file_name.clone())).collect(),
518	            members: entry.inheritance.iter().flat_map(|layer| layer.members.iter().cloned()).collect(),
519	            notable: layer_notable(entry),
520	        }
521	    }
522	}
523	
524	/// What the merge of the checker's answer into a component's structural answer is decided from besides the answer:
525	/// that structural answer's [`LayerFacts`] and the run's [`CollapseContext`]. A checker given it converts only the props
526	/// the merge keeps ([`Layering::kept`]), so the merge must be asked with the same structural answer and the same context:
527	/// otherwise it may keep a prop the checker did not convert ([`unconverted_type`]).
528	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
529	pub struct Layering {
530	    /// The structural answer's facts.
531	    pub facts: LayerFacts,
532	    /// The run's collapse choices.
533	    pub cx: CollapseContext,
534	}
535	
536	impl Layering {
537	    /// The layering of `entry`, a structural answer, under `cx`.
538	    pub fn of(entry: &ComponentEntry, cx: CollapseContext) -> Self {
539	        Self { facts: LayerFacts::of(entry), cx }
540	    }
541	
542	    /// Whether the merge can leave any prop to a layer: the structural answer has a layer, or the run collapses.
543	    pub fn may_layer(&self) -> bool {
544	        !self.facts.members.is_empty() || self.cx.mode != crate::types::options::CollapseInheritedProps::None
545	    }
546	
547	    /// Whether the structural answer lists a prop named `name`: the merge keeps such a prop whatever its source
548	    /// ([`Layering::kept`]), so only a prop it does not list can be left to a layer.
549	    pub fn lists(&self, name: &str) -> bool {
550	        self.facts.listed.contains(name)
551	    }
552	
553	    /// For each prop of a checker's answer, by name, `parent` and whether `@types/react` declares it, in the answer's
554	    /// order: whether the merge (`layer_checker_props`) keeps it. The same decision from the same inputs, read from the
555	    /// [`LayerFacts`] instead of the entry. An `@types/react` prop is always reported kept: whether the merge sees it at
556	    /// all is decided by its own filter first. `picked` is the answer's `SemanticComponent::picked`: those props reach
557	    /// by name and are kept, as the merge keeps them.
558	    pub fn kept(&self, props: &[(&str, Option<&PropParent>, bool)], picked: &[String]) -> Vec<bool> {
559	        let (layers, made) = checker_sources(&self.facts, props.iter().copied(), picked, self.cx);
560	        let layered: rustc_hash::FxHashSet<&str> = self
561	            .facts
562	            .members
563	            .iter()
564	            .map(String::as_str)
565	            .chain(layers.iter().flat_map(|layer| layer.members.iter().map(String::as_str)))
566	            .collect();
567	        props
568	            .iter()
569	            .map(|(name, parent, react_declared)| {
570	                *react_declared
571	                    || keeps(name, *parent, (&self.facts.notable, &made), self.facts.listed.contains(*name), &layered)
572	            })
573	            .collect()
574	    }
575	}
576	
577	/// The type a checker's prop has when the checker did not convert it, because the merge leaves it to a collapsed layer
578	/// ([`Layering::kept`]): its name and `parent` are all a layer reads. It is never merged as a prop's type.
579	pub fn unconverted_type() -> PropType {
580	    degraded_type("unconverted: left to a collapsed layer", OpaqueReason::UnsupportedExpression)
581	}
582	
583	/// What [`checker_sources`] reads of a structural answer.
584	trait Structural {
585	    /// Whether it read `source`: a prop it lists names it as `parent`, or one of its layers is it.
586	    fn reads(&self, source: &PropParent) -> bool;
587	}
588	
589	impl Structural for ComponentEntry {
590	    fn reads(&self, source: &PropParent) -> bool {
591	        self.props.values().any(|prop| prop.parent.as_ref() == Some(source))
592	            || self
593	                .inheritance
594	                .iter()
595	                .any(|layer| layer.type_name == source.name && layer.file_name == source.file_name)
596	    }
597	}
598	
599	impl Structural for LayerFacts {
600	    fn reads(&self, source: &PropParent) -> bool {
601	        self.parents.contains(source)
602	            || self
603	                .sources
604	                .iter()
605	                .any(|(type_name, file_name)| *type_name == source.name && *file_name == source.file_name)
606	    }
607	}
608	
609	/// The layers a checker's answer adds to `structural`'s, and the notable props they hold, to move to
610	/// `notableInherited` ([`layer_checker_props`]'s second rule). `props` are the answer's, by name, `parent` and whether
611	/// `@types/react` declares it, in its order. A prop `picked` names reaches by name: it is neither counted nor held by a
612	/// layer (the first rule's `picked`).
613	fn checker_sources<'p>(
614	    structural: &impl Structural,
615	    props: impl Iterator<Item = (&'p str, Option<&'p PropParent>, bool)>,
616	    picked: &[String],
617	    cx: CollapseContext,
618	) -> (Vec<InheritedLayer>, Vec<(String, PropParent)>) {
619	    // Each source the answer names (a prop's `parent` is an interface), in the order it first names it, with the
620	    // members of it that reach the component, each once; a picked prop is not one.
621	    let mut sources: Vec<(&'p PropParent, Vec<String>)> = Vec::new();
622	    for (name, parent, react_declared) in props {
623	        if picked.iter().any(|key| key == name) {
624	            continue;
625	        }
626	        let Some(parent) = parent.filter(|_| !react_declared) else { continue };
627	        match sources.iter_mut().find(|(source, _)| *source == parent) {
628	            Some((_, names)) if !names.iter().any(|member| member == name) => names.push(name.to_string()),
629	            Some(_) => {}
630	            None => sources.push((parent, vec![name.to_string()])),
631	        }
632	    }
633	    let notable_names = crate::react_types::notable_html_attrs("");
634	    let mut notable = Vec::new();
635	    let mut layers = Vec::new();
636	    for (source, members) in sources {
637	        if structural.reads(source) || !cx.collapses(&source.file_name, &source.name, members.len()) {
638	            continue;
639	        }
640	        notable.extend(
641	            members
642	                .iter()
643	                .filter(|name| notable_names.contains(&name.as_str()))
644	                .map(|name| (name.clone(), source.clone())),
645	        );
646	        layers.push(InheritedLayer {
647	            type_name: source.name.clone(),
648	            file_name: source.file_name.clone(),
649	            omitted: Vec::new(),
650	            html_element: None,
651	            total_props: u32::try_from(members.len()).unwrap_or(u32::MAX),
652	            members,
653	        });
654	    }
655	    (layers, notable)
656	}
657	
658	/// A notable prop's name and the collapsed source it belongs to.
659	type Notable = (String, PropParent);
660	
661	/// Whether the merge keeps a checker prop named `name` declared in `parent`: a notable member of a layer the entry has
662	/// whose source is `parent` (`notable.0`, [`layer_notable`]), a notable member of a layer the answer adds (`notable.1`),
663	/// a prop the structural answer lists itself (`listed`), or one no layer names (`layered`).
664	fn keeps(
665	    name: &str,
666	    parent: Option<&PropParent>,
667	    notable: (&[Notable], &[Notable]),
668	    listed: bool,
669	    layered: &rustc_hash::FxHashSet<&str>,
670	) -> bool {
671	    let (of_entry, made) = notable;
672	    made.iter().any(|(notable, _)| notable == name)
673	        || of_entry.iter().any(|(notable, source)| notable == name && parent == Some(source))
674	        || listed
675	        || !layered.contains(name)
676	}
677	
678	/// Moves each merged prop `notable` names from `entry`'s props to its `notableInherited`, when it is the collapsed
679	/// source's member (its `parent` is that source); a prop of that name the component declares itself stays a prop.
680	pub(crate) fn move_notable(entry: &mut ComponentEntry, notable: &[(String, PropParent)]) {
681	    for (name, source) in notable {
682	        if entry.props.get(name).is_some_and(|prop| prop.parent.as_ref() == Some(source))
683	            && let Some(prop) = entry.props.remove(name)
684	        {
685	            entry.notable_inherited.insert(name.clone(), prop);
686	        }
687	    }
688	}
689	
690	/// What one merged prop was made from, by identity: the checker's prop, the structural prop of the same name, the
691	/// union a prop without a `parent` writes in the entry's file (a prop with one finds it by itself) and the code
692	/// default, each by address (`0` for none). The first two are shared copies
693	/// (the backend's and the resolver's interners), so the components of a design system that share a prop share its key.
694	type MergeKey = (usize, usize, (usize, usize), usize);
695	
696	/// The props one merge has made, by what they were made from ([`MergeKey`]). A merged prop is a function of those
697	/// inputs and the merge's [`ResolverFacts`] alone, so a prop made from the same ones is the one made before: it skips
698	/// the copy, the reordering and the interning of a type that is often hundreds of members wide. Each entry holds the
699	/// two props its key points at, so neither is freed and its address taken by another prop while the merge runs.

