112	fn the_structural_and_the_checker_lane_give_the_same_layers_and_props() {
113	    let (_dir, root) = project();
114	    let mut checked = 0;
115	    for load_dependencies in [true, false] {
116	        for collapse in
117	            [CollapseInheritedProps::Dependencies, CollapseInheritedProps::All, CollapseInheritedProps::None]
118	        {
119	            for html_attributes in [HtmlAttributeMode::Full, HtmlAttributeMode::None] {
120	                let options = PipelineOptions {
121	                    src_dirs: vec![root.clone()],
122	                    use_cache: false,
123	                    load_dependencies,
124	                    collapse_inherited_props: collapse,
125	                    html_attributes,
126	                    ..PipelineOptions::default()
127	                };
128	                let structural = extract(&options);
129	                let mut request = SemanticRequest::new(root.clone(), targets_of(&structural));
130	                request.request_timeout = Duration::from_secs(60);
131	                let outcome = resolve(request);
132	                assert_eq!(outcome.fallbacks, [], "the checker answers every component");
133	                let mut checker = structural.clone();
134	                merge_semantic_in(&mut checker, outcome, Default::default(), CollapseContext::of(&options));
135	                // The checker told the merge's layering converts only what the merge keeps: the same output.
136	                let cx = CollapseContext::of(&options);
137	                let mut request = SemanticRequest::new(root.clone(), targets_collapsing(&structural, cx));
138	                request.request_timeout = Duration::from_secs(60);
139	                let mut skipping = structural.clone();
140	                merge_semantic_in(&mut skipping, resolve(request), Default::default(), cx);
141	                assert_eq!(
142	                    skipping.components, checker.components,
143	                    "load={load_dependencies} {collapse:?} {html_attributes:?}: converting only what is kept"
144	                );
145	
146	                for (name, _, _, package) in SOURCES {
147	                    for key in [format!("With{name}"), format!("Omit{name}"), format!("Pick{name}")] {
148	                        let case = format!("{key} load={load_dependencies} {collapse:?} {html_attributes:?}");
149	                        assert_eq!(layers(&checker, &key), layers(&structural, &key), "layers of {case}");
150	                        // A package type the structural lane does not load is read by the checker alone.
151	                        if load_dependencies || !package {
152	                            assert_eq!(props(&checker, &key), props(&structural, &key), "props of {case}");
153	                        }
154	                        checked += 1;
155	                    }
156	                    if !package {
157	                        continue;
158	                    }
159	                    // Only the checker sees this source: the layers are the ones the rule gives a loaded dependency's
160	                    // source of this declared size, the same the structural lane gives `With{name}`.
161	                    let key = format!("Only{name}");
162	                    let case = format!("{key} load={load_dependencies} {collapse:?} {html_attributes:?}");
163	                    let (_, _, count, _) = SOURCES.iter().find(|s| s.0 == *name).unwrap();
164	                    let ambient = name.ends_with("DOMEvents") || name.ends_with("DOMAttributes");
165	                    let threshold = if ambient { 30 } else { 200 };
166	                    let collapses = load_dependencies && collapse != CollapseInheritedProps::None && *count > threshold;
167	                    let pkg = root.join("node_modules/pkg/index.d.ts").to_string();
168	                    let expected: Layers = if collapses {
169	                        [(name.to_string(), pkg, u32::try_from(*count).unwrap(), Vec::new())].into()
170	                    } else {
171	                        Layers::new()
172	                    };
173	                    assert_eq!(layers(&checker, &key), expected, "layers of {case}");
174	                    if load_dependencies {
175	                        assert_eq!(layers(&checker, &key), layers(&checker, &format!("With{name}")), "{case}");
176	                    }
177	                    let listed = props(&checker, &key);
178	                    assert!(listed.contains("w"), "{case}: {listed:?}");
179	                    assert_eq!(listed.len(), if collapses { 1 } else { count + 1 }, "props of {case}");
180	                    checked += 1;
181	                }
182	            }
183	        }
