358	        ("PartialPick250", format!("Partial<Pick<S, {}>>", keys(0..250)), 250),
359	        ("PickAndOwn250", format!("Pick<S, {}> & {{ own?: boolean }}", keys(0..250)), 250),
360	        // A project alias whose whole body is the `Pick`.
361	        ("NamedPick250", "NamedS".to_string(), 250),
362	    ];
363	    let mut text = String::from(
364	        "import type { Huge } from 'pkg';\nimport { WidgetHuge } from 'pkg';\n\
365	         type PropsOf<T> = T extends (props: infer P) => unknown ? P : never;\ntype Seen = PropsOf<typeof WidgetHuge>;\n",
366	    );
367	    for base in ["Huge", "Seen"] {
368	        text.push_str(&format!("type Named{base} = Pick<{base}, {}>;\n", keys(0..250)));
369	    }
370	    for (name, wrapper, _) in &cases {
371	        let structural = wrapper.replace('S', "Huge");
372	        let checker_only = wrapper.replace('S', "Seen");
373	        text.push_str(&format!("export function Struct{name}(props: {structural}) {{ return null; }}\n"));
374	        text.push_str(&format!("export function Only{name}(props: {checker_only}) {{ return null; }}\n"));
375	    }
376	    let package = format!(
377	        "export interface Huge {{ {}}}\nexport interface WidgetHugeProps extends Huge {{ w?: boolean }}\n\
378	         export declare function WidgetHuge(props: WidgetHugeProps): null;\n",
379	        members("h", 700)
380	    );
381	    let (_dir, structural, checker) = both_lanes(&package, &[("Components.tsx", text)]);
382	    for (name, _, listed) in &cases {
383	        for (lane, output, key) in [
384	            ("structural", &structural, format!("Struct{name}")),
385	            ("checker", &checker, format!("Struct{name}")),
386	            ("checker only", &checker, format!("Only{name}")),
387	        ] {
388	            // The checker cannot see a `Pick` a project alias is (`Converter::composes`), and the structural lane
389	            // cannot read `Seen`: this one case collapses (a known limit, not asserted).
390	            if *name == "NamedPick250" && lane == "checker only" {
391	                continue;
392	            }
393	            let entry = &output.components[&key];
394	            assert!(entry.inheritance.iter().all(|layer| layer.type_name != "Huge"), "{lane} {key}: no Huge layer");
395	            let shown = entry.props.keys().filter(|prop| prop.starts_with('h')).count();
396	            assert_eq!(shown, *listed, "{lane} {key}: listed");
397	        }
398	        if *name != "NamedPick250" {
399	            assert_eq!(props(&checker, &format!("Only{name}")), props(&structural, &format!("Struct{name}")), "{name}");
400	        }
401	    }
402	}
403	
404	/// Finding B: a collapsed source's notable prop (`className`) keeps the default the component gives it, its JSDoc and
405	/// its optionality (a default makes it optional; `Partial`, `Required`) in `notableInherited`, the same in both lanes, whether the structural lane
406	/// collapsed the source (the checker's answer merged into its layer) or only the checker read it.
407	#[test]
408	fn finding_b_a_notable_prop_of_a_collapsed_source_keeps_its_default_in_both_lanes() {
409	    let big = |name: &str| {
410	        format!(
411	            "export interface {name} {{ /** The class. */ className: string; {}}}\n\
412	             export interface Widget{name}Props extends {name} {{ w?: boolean }}\n\
413	             export declare function Widget{name}(props: Widget{name}Props): null;\n",
414	            members("b", 201)
415	        )
416	    };
417	    let text = String::from(
418	        "import type { BigBox } from './sources';\nimport { WidgetHugeBox } from 'pkg';\n\
419	         type PropsOf<T> = T extends (props: infer P) => unknown ? P : never;\n\
420	         interface BoxProps extends BigBox { own?: boolean }\n\
421	         export function Box({ className = 'base' }: BoxProps) { return null; }\n\
422	         export function PartialBox({ className = 'base' }: Partial<BigBox>) { return null; }\n\
423	         export function RequiredBox(props: Required<Partial<BigBox>>) { return null; }\n\
424	         export function OnlyBox({ className = 'base' }: PropsOf<typeof WidgetHugeBox>) { return null; }\n\
425	         export function PickedAndLayered(props: Pick<BigBox, 'className'> & Omit<BigBox, 'b0'>) { return null; }\n",
426	    );
427	    let (_dir, structural, checker) =
428	        both_lanes(&big("HugeBox"), &[("sources.ts", big("BigBox")), ("Components.tsx", text)]);
429	    type Notable = (String, bool, Option<String>, String);
430	    let notable = |output: &ExtractionOutput, key: &str| -> Option<Notable> {
431	        let entry = &output.components[key];
432	        assert!(!entry.props.contains_key("className"), "{key}: className is the layer's");
433	        entry.notable_inherited.get("className").map(|prop| {
434	            let source = prop.parent.as_ref().map(|parent| parent.name.clone()).unwrap_or_default();
435	            let default = prop.default_value.as_ref().map(|value| value.value.clone());
436	            (source, prop.required, default, prop.description.clone())
437	        })
438	    };
439	    let expect = |source: &str, required: bool, default: Option<&str>| {
440	        Some((source.to_string(), required, default.map(str::to_string), "The class.".to_string()))
441	    };
442	    for (key, expected) in [
443	        ("Box", expect("BigBox", false, Some("'base'"))),
444	        ("PartialBox", expect("BigBox", false, Some("'base'"))),
445	        ("RequiredBox", expect("BigBox", true, None)),
446	    ] {
447	        assert!(layers(&structural, key).iter().any(|layer| layer.0 == "BigBox"), "{key}: a BigBox layer");
448	        assert_eq!(notable(&structural, key), expected, "structural {key}");
449	        assert_eq!(notable(&checker, key), expected, "checker {key}");
450	    }
451	    // Picked by name and held by a layer through the `Omit`: the structural lane lists it, so the checker lane does.
452	    for (lane, output) in [("structural", &structural), ("checker", &checker)] {
453	        let entry = &output.components["PickedAndLayered"];
454	        assert!(entry.inheritance.iter().any(|layer| layer.type_name == "BigBox"), "{lane}: a BigBox layer");
455	        assert!(entry.props.contains_key("className"), "{lane}: className listed");
456	        assert!(!entry.notable_inherited.contains_key("className"), "{lane}: className not moved");
457	    }
458	    // Only the checker reads this source; its JSDoc is `the_checker_answers_a_props_jsdoc`'s.
459	    let only = notable(&checker, "OnlyBox").map(|(source, required, default, _)| (source, required, default));
460	    assert_eq!(only, Some(("HugeBox".to_string(), false, Some("'base'".to_string()))), "checker only OnlyBox");
461	}
462	
463	/// What one run asked of the checker: every request (a batch's each counted), and the props' symbols whose type it
464	/// asked for (`getTypesOfSymbols`, the first step of converting a prop).
465	#[derive(Debug, Clone, Copy, PartialEq)]
466	struct Asked {
467	    requests: usize,
468	    prop_types: usize,
469	}
470	
471	/// The components `keys` of the project resolved by the checker, each prop converted (`skip` false) or only those the
472	/// merge with `cx` keeps, then merged with `cx` either way; and what the checker was asked.
473	fn resolve_recorded(
474	    root: &Utf8PathBuf,
475	    structural: &ExtractionOutput,
476	    keys: &[&str],
477	    cx: CollapseContext,
478	    skip: bool,
479	) -> (ExtractionOutput, Asked) {
480	    let calls = root.join(format!("calls-{skip}.json"));
481	    let targets = if skip { targets_collapsing(structural, cx) } else { targets_of(structural) };
482	    let targets = targets.into_iter().filter(|target| keys.contains(&target.key.as_str())).collect();
483	    let mut request = SemanticRequest::new(root.clone(), targets);
484	    request.request_timeout = Duration::from_secs(60);
485	    request.record_to = Some(calls.clone());
486	    let outcome = resolve(request);
487	    assert_eq!(outcome.fallbacks, []);
488	    let mut merged = structural.clone();
489	    merge_semantic_in(&mut merged, outcome, Default::default(), cx);
490	    let recorded: Vec<serde_json::Value> = serde_json::from_str(&std::fs::read_to_string(calls).unwrap()).unwrap();
491	    let mut asked = Asked { requests: 0, prop_types: 0 };
492	    let mut count = |method: &serde_json::Value, params: &serde_json::Value| {
493	        asked.requests += 1;
494	        if method == "getTypesOfSymbols" {
495	            asked.prop_types += params["symbols"].as_array().map_or(0, Vec::len);
496	        }
497	    };
498	    for call in &recorded {
499	        if call["method"] == "batchRequests" {
500	            for request in call["params"]["requests"].as_array().into_iter().flatten() {
501	                count(&request["method"], &request["params"]);
502	            }
503	        } else {
504	            count(&call["method"], &call["params"]);
505	        }
506	    }
507	    (merged, asked)
508	}
509	
510	/// A project source of 201 members collapses under the default mode, and so does a package source of 201 the run
511	/// loads: the checker asks for the type of no prop either layer holds, and the merged output is the one converting
512	/// every prop gives. Each component lists its own `own` beside the layer.
513	#[test]
514	fn the_checker_does_not_convert_the_props_a_collapsed_layer_holds() {
515	    let (_dir, root) = project();
516	    let options = PipelineOptions { src_dirs: vec![root.clone()], use_cache: false, ..PipelineOptions::default() };
517	    let structural = extract(&options);
518	    let cx = CollapseContext::of(&options);
519	    let keys = ["WithProjectBig", "WithBigApi"];
520	    let (all, converting_all) = resolve_recorded(&root, &structural, &keys, cx, false);
521	    let (skipped, converting_kept) = resolve_recorded(&root, &structural, &keys, cx, true);
522	
523	    assert_eq!(skipped.components, all.components, "the same output");
524	    for key in keys {
525	        let layer = all.components[key].inheritance.iter().map(|layer| layer.members.len()).sum::<usize>();
526	        assert!(layer >= 200, "{key} has a collapsed layer: {layer}");
527	        assert!(all.components[key].props.contains_key("own"), "{key} lists `own`");
528	    }
529	    // `ProjectBig`'s 201 members and `BigApi`'s 201.
530	    let layered = 201 + 201;
531	    assert!(
532	        converting_all.prop_types >= converting_kept.prop_types + layered,
533	        "the layered props' types are not asked for: {converting_all:?} vs {converting_kept:?}"
534	    );
535	    assert!(converting_kept.requests < converting_all.requests, "{converting_kept:?} vs {converting_all:?}");
536	}
537	
538	/// A project source of 200 members, at the threshold, does not collapse: every prop is converted, as before.
539	#[test]
540	fn a_source_under_the_threshold_is_still_converted_in_full() {
541	    let (_dir, root) = project();
542	    let options = PipelineOptions { src_dirs: vec![root.clone()], use_cache: false, ..PipelineOptions::default() };
543	    let structural = extract(&options);
544	    let cx = CollapseContext::of(&options);
545	    let keys = ["WithProjectEdge"];
546	    let (all, converting_all) = resolve_recorded(&root, &structural, &keys, cx, false);
547	    let (skipped, converting_kept) = resolve_recorded(&root, &structural, &keys, cx, true);
548	
549	    assert_eq!(skipped.components, all.components, "the same output");
550	    assert!(all.components["WithProjectEdge"].inheritance.is_empty(), "no layer");
551	    assert_eq!(all.components["WithProjectEdge"].props.len(), 201, "200 members and `own`");
552	    assert_eq!(converting_kept.prop_types, converting_all.prop_types, "every prop's type is asked for");
553	    assert!(converting_kept.prop_types >= 201, "{converting_kept:?}");
554	}
